grid=[[0]*16 for _ in range(14)]
markers=[(2,1),(2,5),(3,12),(6,3),(7,10),(9,14),(11,10),(12,5)]
template=[[1,2,2],[9,1,9],[0,0,3]]
# Keep the source template at rows 10-12, cols 0-2, and stamp around markers.
for r,c in markers:
    for dr in range(-1,2):
        for dc in range(-1,2):
            v=template[dr+1][dc+1]
            rr,cc=r+dr,c+dc
            if v and 0<=rr<14 and 0<=cc<16:
                grid[rr][cc]=v
for row in grid: print(row)
print('row_lengths', [len(row) for row in grid])
